window.TESTS = window.TESTS || [];
TESTS.push({
id: 2, name: "多益 2",
sets: [
{ part: 5, title: "Part 5 單句填空", qs: [
{n:1,q:"We are going to _____ in the morning to go over our strategy for the following days.",qz:"我們早上要集合，檢討接下來幾天的策略。",o:["wait","gather","explain","astound"],oz:["等待","聚集","解釋","使震驚"],a:1,ex:"go over our strategy（一起檢討策略）需要大家「聚集」→ gather。explain 是及物動詞需接受詞；astound 語意不合。"},
{n:2,q:"The man was so _____ in the television program that he didn't hear someone call his name.",qz:"那個人太專注於電視節目，以致於沒聽到有人叫他的名字。",o:["engage","engaged","engaging","engagement"],oz:["從事（原形）","專注的","引人入勝的","訂婚／參與（名詞）"],a:1,ex:"so…that… 中 so 後接形容詞；人「全神貫注於」→ be engaged in。engaging 是「事物很吸引人」。"},
{n:3,q:"These items are _____ in price and quality, so it's really a matter of what your own preference is in color and weight.",qz:"這些商品在價格和品質上不相上下，所以真的就看你對顏色和重量的偏好。",o:["compare","comparing","comparison","comparable"],oz:["比較（動詞）","比較中","比較（名詞）","差不多的、可比的"],a:3,ex:"be 動詞後接形容詞 → comparable（相當的、不相上下的）。"},
{n:4,q:"_____ as Nelson was about to walk out the door, his mobile phone rang.",qz:"就在尼爾森正要走出門時，他的手機響了。",o:["Just","Away","Much","Around"],oz:["正好、就在","離開","非常","大約"],a:0,ex:"just as（就在…的時候）為固定搭配，搭配 was about to（正要）。"},
{n:5,q:"You should be able to pick up your driver's license about a week after you file for it with all the _____ information.",qz:"你備齊所有必要資料提出申請後，大約一週就能領到駕照。",o:["steady","asking","requisite","desperate"],oz:["穩定的","詢問中","必需的","絕望的"],a:2,ex:"申請駕照需要「必要的」資料 → requisite information。"},
{n:6,q:"Could you help me _____ how much paint I will need for three rooms in my house?",qz:"你可以幫我算出家裡三個房間需要多少油漆嗎？",o:["determined","determining","determine","determination"],oz:["已決定的","決定中","確定、算出（原形）","決心（名詞）"],a:2,ex:"help + 受詞 + 原形動詞（或 to V）→ help me determine。"},
{n:7,q:"Did you say you have a _____ in mind for overcoming recent customer dissatisfaction?",qz:"你是說你已經想好一個策略，來化解最近顧客的不滿嗎？",o:["strata","strategy","strategic","strategize"],oz:["地層（複數）","策略（名詞）","策略的","制定策略（動詞）"],a:1,ex:"冠詞 a 後接單數名詞 → strategy；have something in mind（心中已有…）。"},
{n:8,q:"I'm afraid that kind of behavior is _____ unacceptable for someone who knows me so well.",qz:"恐怕對一個這麼了解我的人來說，那種行為根本無法接受。",o:["simply","frantically","deliberately","courageously"],oz:["簡直、根本","瘋狂地","故意地","勇敢地"],a:0,ex:"副詞修飾形容詞 unacceptable，表強調「根本、完全」→ simply。"},
{n:9,q:"If we _____ all that supporting sales data, the client might have otherwise backed out of the deal.",qz:"如果我們當初沒有提供所有那些佐證的銷售資料，客戶可能就會退出這筆交易了。",o:["wasn't provided","wouldn't provide","don't provide","hadn't provided"],oz:["沒被提供","不會提供","不提供","當初沒有提供"],a:3,ex:"主句 might have backed out 是「與過去事實相反」的假設語氣 → if 子句用過去完成式 hadn't provided。"},
{n:10,q:"Only in _____ circumstances can employees at the company take a leave of more than two weeks.",qz:"只有在特殊情況下，公司員工才能請超過兩週的假。",o:["except","exception","exceptional","exceptionally"],oz:["除了","例外（名詞）","特殊的","格外地"],a:2,ex:"修飾名詞 circumstances 用形容詞 → exceptional circumstances（特殊情況）。Only + 副詞片語置首，句子倒裝 can employees…。"},
{n:11,q:"I'm in need of a(n) _____ contractor who can repair our leaking pool in the backyard.",qz:"我需要一位信譽良好的承包商來修理後院漏水的泳池。",o:["arguable","reputable","opposable","perceivable"],oz:["有爭議的","信譽好的","可對立的","可察覺的"],a:1,ex:"找承包商當然要找「信譽良好的」→ reputable。"},
{n:12,q:"I think the season finale revealed a lot of _____ tension between Tina and Bulldog, especially in their last conversation.",qz:"我覺得這季的最後一集揭露了蒂娜和鬥牛犬之間許多潛藏的緊張關係，尤其是在他們最後一段對話中。",o:["relaxed","angular","implicit","eponymous"],oz:["放鬆的","有稜角的","隱含的","同名的"],a:2,ex:"revealed（揭露）的是原本「隱含、未明說」的緊張 → implicit tension。"},
{n:13,q:"The store will be closing in 15 minutes. Please _____ the items you wish to purchase and make your way to the cashier.",qz:"本店將在 15 分鐘後打烊。請挑選您想購買的商品並前往收銀台。",o:["select","be select","selecting","going to select"],oz:["挑選（原形）","（錯誤用法）","挑選中","將要挑選"],a:0,ex:"Please 後接原形動詞的祈使句，且與 make your way 對等 → select。"},
{n:14,q:"I have a lot of things to give _____ before I move to the East Coast next month.",qz:"下個月搬到東岸之前，我有很多東西要送人。",o:["to","in","with","away"],oz:["給","屈服","與","送掉"],a:3,ex:"give away（送掉、贈送）；give in 是「屈服」。搬家前把東西送人 → away。"},
{n:15,q:"Next time we see each other, I _____ married.",qz:"下次我們見面時，我就已經結婚了。",o:["am","will","have gotten","will have gotten"],oz:["是","將","已經（現在完成）","到時將已經（未來完成）"],a:3,ex:"Next time…（未來某時點）之前已完成 → 未來完成式 will have gotten married。"},
{n:16,q:"_____ several problems, Elsa was confident that her latest enterprise would be a success.",qz:"儘管有幾個問題，艾莎仍有信心她最新的事業會成功。",o:["After","Again","Before","Despite"],oz:["在…之後","再次","在…之前","儘管"],a:3,ex:"有問題 vs. 仍有信心 → 讓步；後接名詞 several problems → 介系詞 Despite。"},
{n:17,q:"Letitia has been getting so much _____ in her inbox that she missed important e-mails.",qz:"萊蒂西亞的收件匣收到太多垃圾郵件，以致於她錯過了重要的信。",o:["dam","cram","spam","wham"],oz:["水壩","死記硬背","垃圾郵件","重擊聲"],a:2,ex:"收件匣裡的大量信件 → spam（垃圾郵件）。"},
{n:18,q:"If you are not the intended _____ of this e-mail, please delete it.",qz:"如果您不是這封郵件的指定收件人，請將它刪除。",o:["receive","recipient","receipt","reception"],oz:["收到（動詞）","收件人","收據","接待處／接收"],a:1,ex:"the intended ___ 需要表「人」的名詞 → recipient（收件人）。receipt 是收據。"},
{n:19,q:"This is a friendly reminder to clean all the art tools and place them in the same boxes _____ you found them.",qz:"友善提醒：請清潔所有美術用具，並放回你當初拿出來的那些盒子裡。",o:["when","where","what","how"],oz:["何時","在那裡","什麼","如何"],a:1,ex:"先行詞 the same boxes 是地點，關係副詞用 where（＝in which）。"},
{n:20,q:"Whenever Lena takes a short break from her sandwich stand, she leaves a sign that asks people _____ on the honor system.",qz:"每當莉娜離開三明治攤稍作休息時，她會留一個牌子，請大家自律付款。",o:["paid","to paying","to pay","paying"],oz:["已付","（錯誤用法）","去付款","付款中"],a:2,ex:"ask + 受詞 + to V（要求某人做…）→ asks people to pay。honor system 指誠實自助制度。"},
{n:21,q:"Craig went _____ a shopping spree after receiving his yearly bonus.",qz:"克雷格領到年終獎金後，去瘋狂購物了一番。",o:["in","on","after","under"],oz:["在…裡","從事於","在…之後","在…之下"],a:1,ex:"固定片語 go on a shopping spree（大肆購物）。"},
{n:22,q:"I took a look at the data this morning, and the latest survey results are very _____.",qz:"我今天早上看了數據，最新的調查結果非常令人振奮。",o:["encouragement","encourage","encouraged","encouraging"],oz:["鼓勵（名詞）","鼓勵（動詞）","受到鼓勵的","令人鼓舞的"],a:3,ex:"主詞 results 是「事物」→ 令人振奮的用 -ing：encouraging。encouraged 用於人。"},
{n:23,q:"My number one concern is the safety of my tenants, so I'd like to know if this building has a fire _____.",qz:"我最在乎的是房客的安全，所以想知道這棟建築是否有逃生梯（防火逃生口）。",o:["man","escape","answer","method"],oz:["消防員","逃生口","答案","方法"],a:1,ex:"fire escape（逃生梯、火災逃生口）是固定複合名詞，與安全相關。"},
{n:24,q:"Being British _____, Ralph was amused by the stereotypical image of Brits being gentlemen.",qz:"身為英國人，雷夫自己覺得「英國人都是紳士」這種刻板印象很好笑。",o:["him","he","his","himself"],oz:["他（受格）","他（主格）","他的","他自己"],a:3,ex:"反身代名詞 himself 放在後面表強調「他本身就是英國人」。"},
{n:25,q:"Many children have missed school this week _____ there has been an outbreak of the flu.",qz:"這週很多孩子沒去上學，因為爆發了流感。",o:["as","unless","however","therefore"],oz:["因為","除非","然而","因此"],a:0,ex:"後句是缺課的原因，連接兩個子句 → as（＝because）。however/therefore 是副詞，不能直接連接子句。"},
{n:26,q:"I'm still trying to grasp the _____ of this new accounting system.",qz:"我還在努力搞懂這套新會計系統的來龍去脈（細節）。",o:["ins and outs","rights and lefts","ups and downs","back and forth"],oz:["來龍去脈、細節","（無此慣用語）","起伏、興衰","來回"],a:0,ex:"the ins and outs of something（某事的詳細內容、門道），與 grasp（理解）搭配。"},
{n:27,q:"Being a reader of questionable news sources, Daniel always believes that there's some massive conspiracy _____.",qz:"由於丹尼爾常看可疑的新聞來源，他總相信有什麼大陰謀正在進行。",o:["afoot","on foot","near foot","underfoot"],oz:["進行中、醞釀中","步行","（無此說法）","在腳下"],a:0,ex:"afoot ＝ 正在進行／醞釀（多用於壞事），常說 something is afoot。on foot 是「步行」。"},
{n:28,q:"The two companies are set to _____ into a single corporate entity by the middle of next year.",qz:"這兩家公司預計在明年年中前合併成一家企業。",o:["merge","contend","compete","announce"],oz:["合併","爭奪","競爭","宣布"],a:0,ex:"into a single entity（成為單一實體）→ merge into（合併成）。"},
{n:29,q:"All entries _____ equally, so each has a fair chance of winning the award.",qz:"所有參賽作品都受到同等評審，所以每件都有公平的得獎機會。",o:["judgmental","judge","are judged","have judged"],oz:["愛批判的","評審（主動）","被評審","已評審（主動）"],a:2,ex:"作品是「被」評審的 → 被動語態 are judged。"},
{n:30,q:"Most companies will only resort to layoffs if everything _____ has been tried.",qz:"大多數公司只有在其他方法都試過之後，才會訴諸裁員。",o:["since","then","ever","else"],oz:["自從","然後","曾經","其他"],a:3,ex:"everything else（其他所有事情）。"}
]},
{ part: 6, title: "Part 6｜Best Airlines 新航線",
passage: `<p>Best Airlines is proud to announce route __(31)__ in Asia and Oceania. Starting January 1, Best __(32)__ from Tokyo to Singapore, Kuala Lumpur, Auckland, and Sydney.</p><p>Throughout the month of January, all __(33)__ class passengers will receive the premium service package at 50 percent off. __(34)__</p>`,
pz: `<p>Best 航空很榮幸宣布在亞洲與大洋洲擴展航線。從 1 月 1 日起，Best 將從東京飛往新加坡、吉隆坡、奧克蘭和雪梨。</p><p>整個 1 月份，所有經濟艙乘客都能以五折享有尊榮服務套餐。只要在報到時輸入折扣碼 BEST50JAN16 即可。</p>`,
qs: [
{n:31,q:"Question 31",o:["expending","expanded","expand","expansion"],oz:["花費中","擴展了","擴展（動詞）","擴展（名詞）"],a:3,ex:"announce 的受詞是名詞 → route expansion（航線擴展）。"},
{n:32,q:"Question 32",o:["has flown","will be flying","flew","would fly"],oz:["已經飛","將會飛","飛了","會飛（假設）"],a:1,ex:"Starting January 1（從 1 月 1 日起）是未來 → 未來進行式 will be flying。"},
{n:33,q:"Question 33",o:["ticket","financial","economy","estimated"],oz:["票","財務的","經濟艙","估計的"],a:2,ex:"___ class passengers → economy class（經濟艙），升級享尊榮套餐打折。"},
{n:34,q:"Question 34",o:["Just enter the discount code BEST50JAN16 at check-in.","Price increases will be based on the date of purchase.","Take advantage of this special during the Christmas holiday.","Seats for the new bus lines will be limited, so buy now."],oz:["只要在報到時輸入折扣碼 BEST50JAN16。","漲價將依購買日期而定。","把握聖誕假期的這個優惠。","新巴士路線座位有限，快買。"],a:0,ex:"前句講五折優惠，接著說明如何使用折扣碼最合理。優惠在 1 月，不是聖誕；是航空不是巴士。"}
]},
{ part: 6, title: "Part 6｜ATTENTION 扒手警告",
passage: `<p>ATTENTION:<br>__(35)__ Please take care of your valuables and do not leave your belongings __(36)__ .</p><p>If you see any __(37)__ activity, telephone 02-2625-1113 or speak to the staff at the __(38)__ you are visiting.</p>`,
pz: `<p>注意：<br>本區有扒手出沒。請保管好您的貴重物品，不要讓隨身物品無人看管。</p><p>如果您發現任何可疑活動，請撥打 02-2625-1113 或告知您所在場所的工作人員。</p>`,
qs: [
{n:35,q:"Question 35",o:["It is customary to first ask them before offering them money.","Early birds can be the first to experience it.","There are pickpockets operating in this area.","Travelers might have a chance to snap a picture of this rare sight."],oz:["習俗上要先詢問再給錢。","早到的人可以搶先體驗。","本區有扒手出沒。","旅客可能有機會拍下這難得的景象。"],a:2,ex:"後面要大家保管好貴重物品、注意可疑活動 → 警告有扒手。"},
{n:36,q:"Question 36",o:["attendant","inattentive","attending","unattended"],oz:["服務員","不專心的","參加中","無人看管的"],a:3,ex:"leave + 受詞 + 形容詞（補語）：leave your belongings unattended（讓物品無人看管）。"},
{n:37,q:"Question 37",o:["delicious","suspicious","auspicious","expeditious"],oz:["美味的","可疑的","吉利的","迅速的"],a:1,ex:"看到「可疑的」活動就報案 → suspicious activity。auspicious 是吉祥的，別混淆。"},
{n:38,q:"Question 38",o:["establishment","installment","reimbursement","announcement"],oz:["場所、機構","分期付款","退款","公告"],a:0,ex:"the staff at the ___ you are visiting → 你所在的「場所／店家」→ establishment。"}
]},
{ part: 6, title: "Part 6｜CrossNational Airway 停飛",
passage: `<p>On November 22, 2016, CrossNational Airway abruptly canceled all of its flights, stranding more than 6,000 ticket __(39)__ for the day and affecting 94 domestic and international routes. The airline has had three fatal crashes in the past four years. __(40)__.</p><p>The company also lost approximately US$46 million over 2015 and about US$50 million during its first six months of __(41)__ in 2016. __(42)__ , the company's safety practices have been investigated, and some of its pilots have been grounded after they failed several crucial tests.</p>`,
pz: `<p>2016 年 11 月 22 日，CrossNational 航空突然取消所有航班，使當天超過 6,000 名持票旅客受困，並影響 94 條國內與國際航線。這家航空公司過去四年內發生過三起致命空難。第一起在 2014 年，另外兩起在一年後。</p><p>該公司在 2015 年也虧損約 4,600 萬美元，2016 年前六個月營運又虧損約 5,000 萬美元。此外，公司的安全措施已遭到調查，部分機師在多項關鍵測試不及格後被停飛。</p>`,
qs: [
{n:39,q:"Question 39",o:["holders","planners","travelers","consumers"],oz:["持有人","規劃者","旅客","消費者"],a:0,ex:"ticket holders（持票人）為固定搭配。"},
{n:40,q:"Question 40",o:["The railway had never experienced this type of event before.","People were left wondering how four crashes could have occurred.","The first was in 2014, and the other two were a year later.","This was deemed unacceptable for a three-year span."],oz:["這條鐵路從未發生過這種事。","大家不解四起空難怎麼會發生。","第一起在 2014 年，另外兩起在一年後。","這在三年內被認為無法接受。"],a:2,ex:"承接「過去四年三起空難」補充細節。(A) 是鐵路；(B) 數字錯成四起；(D) 年數錯成三年。"},
{n:41,q:"Question 41",o:["operation","operate","operational","operator"],oz:["營運（名詞）","營運（動詞）","營運的","操作員"],a:0,ex:"介系詞 of 後接名詞 → operation（營運）。"},
{n:42,q:"Question 42",o:["Actually","Similarly","Additionally","Consequently"],oz:["事實上","同樣地","此外","因此"],a:2,ex:"前面講虧損，後面再補充「安全遭調查、機師停飛」另一件壞事 → Additionally（此外）。"}
]},
{ part: 6, title: "Part 6｜Dear PriceMax 青醬",
passage: `<p>Dear PriceMax,</p><p>My name is Rita McCullough, and I'm a new customer. During my first visit to your store, I purchased your Copeland Signature Basil Pesto, brought it home, and used it when making dinner for my family. It would be an __(43)__ to say that it was simply a smash hit. My husband and children absolutely loved it. __(44)__</p><p>Now, imagine my surprise upon discovering that the PriceMax nearest me inexplicably no longer carries this most delicious __(45)__ sauces. For weeks I've waited, a shell of a person, hoping to one day close the deep spiritual void __(46)__ only Copeland Pesto can fill. Please, please, please bring Copeland Pesto back, or at least tell me which PriceMax stores near Edmonton, Alberta, Canada carry it.</p>`,
pz: `<p>親愛的 PriceMax：</p><p>我叫 Rita McCullough，是新顧客。我第一次到你們店裡時，買了 Copeland 招牌羅勒青醬，帶回家為家人做晚餐時用了它。說它大受歡迎還太輕描淡寫了。我先生和孩子們都超愛。我們全家一致認為從沒吃過更好的醬料。</p><p>想像一下，當我發現離我最近的 PriceMax 莫名其妙不再販售這款最美味的醬料時，我有多驚訝。好幾週以來我像行屍走肉般等待著，盼望有一天能填補那只有 Copeland 青醬才能填滿的心靈空洞。拜託、拜託請把 Copeland 青醬帶回來，或至少告訴我加拿大亞伯達省艾德蒙頓附近哪幾家 PriceMax 有賣。</p>`,
qs: [
{n:43,q:"Question 43",o:["exaggeration","overstatement","embellishment","understatement"],oz:["誇大","言過其實","潤飾","輕描淡寫"],a:3,ex:"說它 a smash hit（大受歡迎）還「太保守」→ understatement，表示實際上更好。"},
{n:44,q:"Question 44",o:["It contains a higher concentration of sodium than other brands.","We use basil pesto as an accompaniment to many roast dishes.","The label says the sauce is made of 100 percent imported Italian basil.","All of us unanimously agreed that we had never tasted a better sauce."],oz:["它的鈉含量比其他品牌高。","我們把青醬當作許多烤肉料理的配料。","標籤說醬料用 100% 義大利進口羅勒製成。","我們全家一致認為從沒吃過更好的醬料。"],a:3,ex:"前句「先生和孩子都超愛」，接「全家一致認為最好吃」最連貫。"},
{n:45,q:"Question 45",o:["at","to","of","with"],oz:["在","到","…之中的","與"],a:2,ex:"the most + 形容詞 + of + 複數名詞（…之中最…的）→ the most delicious of sauces。"},
{n:46,q:"Question 46",o:["that","then","though","thus"],oz:["關係代名詞","然後","雖然","因此"],a:0,ex:"先行詞 void，後面 only Copeland Pesto can fill 缺受詞 → 關係代名詞 that。"}
]},
{ part: 7, title: "Part 7｜租車的訊息",
passage: `<p><b>JAMES MUELLER (11:09 a.m.)</b><br>Did you get the rental car squared away?</p><p><b>TRACY ROBERTS (11:13 a.m.)</b><br>I did, but they were completely out of SUVs, so I had to book a compact. Will that be OK?</p><p><b>JAMES MUELLER (11:14 a.m.)</b><br>No, that's not going to cut it. You know we will have seven people in our party, so we absolutely need the biggest SUV the rental car company has.</p><p><b>TRACY ROBERTS (11:16 a.m.)</b><br>Well, what do you want me to do? All they have left are sedans and compacts.</p><p><b>JAMES MUELLER (11:19 a.m.)</b><br>Then rent out two luxury sedans. I'm not having the CEO of our company squeeze into a tiny car. I really need you to get this done. Don't mess it up like last time.</p><p><b>TRACY ROBERTS (11:21 a.m.)</b><br>OK, that's a good idea. I'll take care of it. Don't worry.</p>`,
pz: `<p><b>James Mueller（上午 11:09）</b><br>租車的事搞定了嗎？</p><p><b>Tracy Roberts（11:13）</b><br>搞定了，但他們的休旅車全租光了，所以我只好訂一台小型車。這樣可以嗎？</p><p><b>James Mueller（11:14）</b><br>不行，那樣不夠。你知道我們一行有七個人，所以一定要租那家公司最大台的休旅車。</p><p><b>Tracy Roberts（11:16）</b><br>那你要我怎麼辦？他們只剩轎車和小型車了。</p><p><b>James Mueller（11:19）</b><br>那就租兩台豪華轎車。我不會讓公司的執行長擠進小車裡。我真的需要你把這件事辦好。別像上次那樣搞砸。</p><p><b>Tracy Roberts（11:21）</b><br>好，這是個好主意。我會處理。別擔心。</p>`,
qs: [
{n:47,q:"What is implied about Tracy Roberts?",qz:"關於 Tracy Roberts，文中暗示了什麼？",o:["She has messed up in the past.","She is really good at her job.","She is the boss.","She does not know how to drive."],oz:["她以前搞砸過。","她工作能力很好。","她是老闆。","她不會開車。"],a:0,ex:"James 說「Don't mess it up like last time」→ 她上次搞砸過。"},
{n:48,q:"At 11:16 a.m., what does Tracy Roberts mean when she writes, \"Well, what do you want me to do\"?",qz:"11:16 時，Tracy 寫「那你要我怎麼辦」是什麼意思？",o:["She is unable to think of a better solution.","She prefers to be given orders.","She's asking the man to give her a suggestion.","She thinks the situation is unacceptable."],oz:["她想不出更好的辦法。","她比較喜歡被命令。","她在請男方給建議。","她認為這情況無法接受。"],a:0,ex:"後面接「他們只剩轎車和小型車」，表示她已無計可施、想不到別的辦法。這是無奈的語氣，不是真的在請教。"}
]},
{ part: 7, title: "Part 7｜圖書館逾期通知",
passage: `<p>The library wishes to notify BLACKMORE, EVAN that the patron has two items overdue. The return date was 12/13. Please return these items ASAP to avoid incurring further charges. Your account has been suspended until the library receives all overdue items. Please call 228-2218 with any questions. Do not reply to this automated message.</p>`,
pz: `<p>圖書館在此通知 BLACKMORE, EVAN：您有兩件資料逾期未還。歸還日期為 12/13。請盡快歸還，以免產生更多費用。在圖書館收到所有逾期資料前，您的帳戶將被停權。如有任何問題請撥 228-2218。請勿回覆此自動訊息。</p>`,
qs: [
{n:49,q:"What do we know about Evan Blackmore?",qz:"關於 Evan Blackmore 我們知道什麼？",o:["He is a criminal.","He works at a library.","His library card has expired.","He's forgotten to return library materials."],oz:["他是罪犯。","他在圖書館工作。","他的借書證過期了。","他忘了歸還圖書館資料。"],a:3,ex:"通知說他有兩件資料逾期（overdue）→ 忘了還書。帳戶是被「停權」不是「過期」。"},
{n:50,q:"When is the return date for the overdue books?",qz:"逾期書籍的歸還日期是什麼時候？",o:["December 2","December 13","February 28","February 18"],oz:["12 月 2 日","12 月 13 日","2 月 28 日","2 月 18 日"],a:1,ex:"The return date was 12/13（美式月/日）→ 12 月 13 日。"}
]},
{ part: 7, title: "Part 7｜A Story of Strings 紀錄片",
passage: `<p>From: a.garrison@mail.com<br>To: penny@pennylane.com<br>Subject: Looking for the digital version of A Story of Strings</p><p>Dear Ms. Lane,</p><p>I recently read your wonderful book <i>A Story of Strings</i> and thoroughly enjoyed the way you wove so much historical material into an enjoyable personal narrative. I learned so much about the history of string instruments through your interviews with musicians and historians.</p><p>I see that you also made a documentary film of the same name; however, I can only find it on DVD. Is it possible to buy and download it as a digital file? As I am traveling abroad extensively at the moment, it's rather inconvenient to get physical mail or packages.</p><p>Many thanks for your reply,</p><p>Andrew Garrison</p>`,
pz: `<p>寄件者：a.garrison@mail.com<br>收件者：penny@pennylane.com<br>主旨：尋找《弦之故事》的數位版</p><p>親愛的 Lane 女士：</p><p>我最近讀了您精彩的著作《弦之故事》，非常喜歡您將大量歷史資料融入引人入勝的個人敘事的方式。透過您對音樂家與歷史學家的訪談，我學到了很多弦樂器的歷史。</p><p>我看到您也拍了一部同名紀錄片，但我只找得到 DVD 版。請問是否能購買並下載數位檔案？由於我目前長時間在國外旅行，收實體郵件或包裹相當不便。</p><p>非常感謝您的回覆，</p><p>Andrew Garrison</p>`,
qs: [
{n:51,q:"What is the main purpose of the e-mail?",qz:"這封郵件的主要目的是什麼？",o:["To express admiration","To get an expert opinion","To inquire about a product","To propose a collaboration"],oz:["表達欽佩","徵求專家意見","詢問產品","提議合作"],a:2,ex:"雖然開頭稱讚了書，但主旨與重點是詢問紀錄片是否有數位版可買 → 詢問產品。"},
{n:52,q:"Why is Andrew Garrison looking for the digital version of the documentary?",qz:"Andrew Garrison 為什麼在找紀錄片的數位版？",o:["The DVDs are sold out.","His laptop doesn't have a DVD drive.","He doesn't currently have a fixed address.","He doesn't like to clutter his home with purchases."],oz:["DVD 賣完了。","他的筆電沒有光碟機。","他目前沒有固定住址。","他不喜歡買東西把家裡塞滿。"],a:2,ex:"他正在國外長途旅行，不方便收實體郵件 → 沒有固定地址。"}
]},
{ part: 7, title: "Part 7｜Ensberg 電影節",
passage: `<p><b>Announcing the 10th Annual Ensberg Film Festival!</b></p><p>June 2017 marks the return of the popular Ensberg Film Festival. Buy your month-long pass now and receive access to every showing for the entirety of the festival, with a total of eight films each weekend for the entire month. This year, the theme of the festival is family. As usual, every film must involve the annual theme in some way in order to be eligible for screening. However, just because the theme is family doesn't mean that every film shown will be family friendly. See below for additional details.</p><p><b>Festival Time:</b><br>Every Saturday and Sunday of June 2017, from 2:00 p.m. to 11:00 p.m.</p><p><b>Price per Pass:</b><br>C$200</p><p><b>Location:</b><br>The Grace Dougherty Theater<br>112 Oxford Road, Ensberg<br>British Columbia, Canada</p><p>If you wish to submit a film for consideration, please send a physical copy to:<br>145 Uniblab Street, Ensberg<br>British Columbia, Canada<br>T54 66E</p><p>Or, upload your digital copy to our Dropbox folder:<br>Folder name: "Ensbergfilm"<br>Accessible through the following e-mail address:<br><u>enserbergfilm@cinephile.com</u></p><p>We hope to see you all there!</p>`,
pz: `<p><b>第十屆 Ensberg 電影節開跑！</b></p><p>2017 年 6 月，廣受歡迎的 Ensberg 電影節回來了。現在購買整月通行證，即可觀賞整個影展期間的所有場次，整個月每個週末共放映八部電影。今年影展的主題是「家庭」。依照慣例，每部電影都必須以某種方式與年度主題相關，才有資格放映。不過，主題是家庭並不代表每部放映的電影都適合闔家觀賞。詳情見下方。</p><p><b>影展時間：</b>2017 年 6 月每個週六、週日，下午 2 點到晚上 11 點。</p><p><b>通行證價格：</b>加幣 200 元</p><p><b>地點：</b>Grace Dougherty 戲院，Ensberg 牛津路 112 號，加拿大卑詩省</p><p>若想投稿電影參選，請將實體拷貝寄至：Ensberg Uniblab 街 145 號，加拿大卑詩省 T54 66E</p><p>或將數位檔上傳至我們的 Dropbox 資料夾「Ensbergfilm」，透過電子郵件 enserbergfilm@cinephile.com 存取。</p><p>希望在那裡見到大家！</p>`,
qs: [
{n:53,q:"If there are four full weekends in the month of June, 2017, how many films will be shown at the festival in total?",qz:"如果 2017 年 6 月有四個完整週末，影展總共會放映幾部電影？",o:["8","16","32","64"],oz:["8","16","32","64"],a:2,ex:"每個週末 8 部 × 4 個週末 ＝ 32 部。"},
{n:54,q:"Where does the film festival take place?",qz:"影展在哪裡舉行？",o:["At the Ensberg Theater","At a theater on Oxford Road","At the British Columbia Theater","At a theater on Uniblab Street"],oz:["在 Ensberg 戲院","在牛津路上的一家戲院","在卑詩省戲院","在 Uniblab 街的一家戲院"],a:1,ex:"Location：The Grace Dougherty Theater, 112 Oxford Road。Uniblab Street 是寄送投稿影片的地址，是陷阱。"}
]},
{ part: 7, title: "Part 7｜Moms on Wheels 雜誌續訂",
passage: `<p>Dear Customer,</p><p>Your subscription to <i>Moms on Wheels</i> is expiring on December 31. —[1]—</p><p>In the upcoming year, <i>Moms on Wheels</i> will bring you interviews with female authors who cycled as their means of travel, tips for minor DIY repairs on the road, and product recommendations. Look out for monthly giveaways on our blog! —[2]—<br><u>www.momsonwheels.com/blog.html</u></p><p>—[3]— Your renewal subscription prices are as follows:<br>• Six months / two issues - $22.00 (save 10% off the newsstand price)<br>• One year / four issues - $40.00 (save 20% off the newsstand price)<br>• Two years / eight issues - $65.00 (save 35% off the newsstand price)</p><p><u>Special offer:</u><br>Buy a two-year subscription and receive a free six-month subscription to give as a gift to a friend. —[4]—</p><p>Sincerely,</p><p>Colby O'Bryant<br>Managing Editor<br>Moms on Wheels</p>`,
pz: `<p>親愛的顧客：</p><p>您訂閱的《Moms on Wheels》將於 12 月 31 日到期。—[1]— 請務必今天續訂，以免錯過任何一期。</p><p>在新的一年，《Moms on Wheels》將為您帶來以單車旅行的女性作家訪談、旅途中小型 DIY 維修技巧以及產品推薦。請留意我們部落格上的每月贈獎活動！—[2]—<br>www.momsonwheels.com/blog.html</p><p>—[3]— 您的續訂價格如下：<br>• 六個月／兩期 － $22.00（比零售價省 10%）<br>• 一年／四期 － $40.00（省 20%）<br>• 兩年／八期 － $65.00（省 35%）</p><p><u>特別優惠：</u><br>訂閱兩年，即可獲贈一份免費的六個月訂閱，可送給朋友當禮物。—[4]—</p><p>Moms on Wheels 執行編輯<br>Colby O'Bryant 敬上</p>`,
qs: [
{n:55,q:"What is something Moms on Wheels subscribers could most likely receive only by subscribing to the company's free blog?",qz:"《Moms on Wheels》的訂戶最可能「只有」訂閱公司的免費部落格才能得到什麼？",o:["A chance to win prizes","Advice on fixing bicycles","Inspiring stories of female travelers","Lists of tested and recommended goods"],oz:["贏得獎品的機會","修理單車的建議","女性旅行者的勵志故事","經測試的推薦商品清單"],a:0,ex:"「Look out for monthly giveaways on our blog!」→ 贈獎活動在部落格上。其他三項是雜誌內容。"},
{n:56,q:"How much would it cost to buy a two-year subscription for yourself, a one-year subscription for one friend, and a six-month subscription for another?",qz:"幫自己買兩年訂閱、幫一位朋友買一年、另一位朋友買六個月，總共要花多少錢？",o:["$80.00","$105.00","$110.00","$127.00"],oz:["$80.00","$105.00","$110.00","$127.00"],a:1,ex:"兩年 $65 會「免費送」一份六個月訂閱，所以只需再付一年 $40 → 65 + 40 = $105。"},
{n:57,q:"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"Be sure to renew it today to avoid missing an issue.\"",qz:"下列句子最適合放在哪個位置？\n「請務必今天續訂，以免錯過任何一期。」",o:["[1]","[2]","[3]","[4]"],oz:["[1]","[2]","[3]","[4]"],a:0,ex:"renew it 的 it 指 subscription，緊接在「您的訂閱將於 12/31 到期」之後最合理 → [1]。"}
]},
{ part: 7, title: "Part 7｜Hearbee Books 優惠",
passage: `<p>From: hearbeebooks.com<br>To: marisa@email4days.com<br>Date received: February 1, 2017</p><p>As a Hearbee Books "A Book a Month" subscriber, you are entitled to take advantage of the following exclusive offer:</p><p style="text-align:center"><b>50% off All Fantasy and Sci-Fi Books</b><br><b>Sale Ends April 1, 2017 at 11:59 P.M. Pacific Time</b></p><p>Disclaimer:<br>This discount is not transferable and cannot be combined with any other offer. This offer is for Hearbee Books online subscribers only. Purchasing additional books on sale or otherwise does not count against or negate the US$7.50 monthly subscription.<br>You received this e-mail at marisa@email4days.com because you are a subscriber to the Hearbee Books "A Book a Month" service.</p><p>If you wish to discontinue this service, contact <u>accounts@hearbeebooks.com</u>.</p>`,
pz: `<p>寄件者：hearbeebooks.com<br>收件者：marisa@email4days.com<br>收件日期：2017 年 2 月 1 日</p><p>身為 Hearbee Books「每月一書」的訂戶，您有權享有以下獨家優惠：</p><p style="text-align:center"><b>所有奇幻與科幻書籍五折</b><br><b>特價至 2017 年 4 月 1 日太平洋時間晚上 11:59 止</b></p><p>免責聲明：<br>此折扣不得轉讓，且不得與其他優惠合併使用。本優惠僅限 Hearbee Books 線上訂戶。額外購買特價或非特價書籍，不會抵扣或取消每月 7.50 美元的訂閱費。<br>您之所以在 marisa@email4days.com 收到這封郵件，是因為您訂閱了 Hearbee Books「每月一書」服務。</p><p>若您想停止此服務，請聯絡 accounts@hearbeebooks.com。</p>`,
qs: [
{n:58,q:"Why is Marisa entitled to this promotion?",qz:"Marisa 為什麼有資格享有這個優惠？",o:["She was randomly selected.","She has purchased over 50 books.","She won Hearbee Books' monthly contest.","She is a subscriber to the Hearbee Books service."],oz:["她被隨機抽中。","她買了超過 50 本書。","她贏了每月競賽。","她是 Hearbee Books 服務的訂戶。"],a:3,ex:"「As a Hearbee Books 'A Book a Month' subscriber, you are entitled…」→ 因為她是訂戶。"},
{n:59,q:"How long will this promotion last?",qz:"這個優惠會持續多久？",o:["1 month","2 months","3 months","Indefinitely"],oz:["1 個月","2 個月","3 個月","無限期"],a:1,ex:"2 月 1 日收到，4 月 1 日結束 → 約 2 個月。"},
{n:60,q:"Based on their titles, which of the following books would NOT be subject to the promotion?",qz:"根據書名，下列哪一本書「不」適用這個優惠？",o:["The Dragon King's Journey: Ascension","Cyborg Future 2221: The Age of the Singularity","The Savage Crystal Chronicles: The Quest for More Wizards","A Painter of Light: A Biography of the Artist Thomas Kinkade"],oz:["龍王之旅：昇華（奇幻）","生化人未來 2221：奇點時代（科幻）","野蠻水晶編年史：尋找更多巫師（奇幻）","光之畫家：藝術家湯瑪斯・金凱德傳記（傳記）"],a:3,ex:"優惠只限奇幻與科幻書。(D) 是畫家的傳記，不屬於這兩類。"}
]},
{ part: 7, title: "Part 7｜軟體專案進度的訊息",
passage: `<p><b>Kool Keith (8:47 a.m.)</b><br>Michael needs an update on the data transfer software. I'll be stopping by his desk in a couple minutes.</p><p><b>Kool Keith (8:49 a.m.)</b><br>Can anyone let me know? He's been pretty tense about the payroll conversion, so I'd like to bring him some good news.</p><p><b>Miranda (8:50 a.m.)</b><br>Sorry, I was in a meeting. The software is right on schedule. Gil is just about finished with the code.</p><p><b>Gil (8:51 a.m.)</b><br>I finished it last night, as a matter of fact. I put in a few hours of overtime to get it done.</p><p><b>Kool Keith (8:51 a.m.)</b><br>Great news, Gil! I know Michael will be very pleased. Anything else I should know before I see him? I know he'll be asking about the budget.</p><p><b>Miranda (8:51 a.m.)</b><br>Looks like the project will be right on budget. Not over, not under. We did a good job managing our resources this time around.</p><p><b>Gil (8:52 a.m.)</b><br>Sounds like Michael's going to have a pretty good morning! Oh, Keith, can I meet with you this afternoon? I've got a few questions about the new handbook.</p><p><b>Kool Keith (8:52 a.m.)</b><br>Sure thing! Let's use Meeting Room C.</p>`,
pz: `<p><b>Kool Keith（上午 8:47）</b><br>Michael 需要資料轉移軟體的最新進度。我幾分鐘後會去他的座位一趟。</p><p><b>Kool Keith（8:49）</b><br>有人能告訴我嗎？他對薪資系統轉換一直很緊繃，所以我想帶點好消息給他。</p><p><b>Miranda（8:50）</b><br>抱歉，我剛在開會。軟體進度完全如期。Gil 的程式碼快寫完了。</p><p><b>Gil（8:51）</b><br>事實上我昨晚就寫完了。我加班了幾個小時把它完成。</p><p><b>Kool Keith（8:51）</b><br>Gil，好消息！我知道 Michael 一定會很高興。去見他之前還有什麼我該知道的嗎？我知道他會問預算。</p><p><b>Miranda（8:51）</b><br>看來專案會剛好符合預算。不超支也沒有剩。這次我們資源管理得很好。</p><p><b>Gil（8:52）</b><br>聽起來 Michael 早上會過得很愉快！喔對了，Keith，今天下午可以跟你碰個面嗎？我有幾個關於新員工手冊的問題。</p><p><b>Kool Keith（8:52）</b><br>當然！我們用 C 會議室吧。</p>`,
qs: [
{n:61,q:"What are the speakers mainly talking about?",qz:"對話者主要在談論什麼？",o:["The employee handbook","A problem with unpaid overtime","An issue with a paycheck","The status of a project"],oz:["員工手冊","無薪加班的問題","薪水的問題","專案的進度"],a:3,ex:"整段都在回報軟體專案的進度與預算。手冊只在最後順帶一提。"},
{n:62,q:"Whose responsibility is the completion of the software?",qz:"完成軟體是誰的責任？",o:["Gil and Michael","Miranda and Gil","Michael and Keith","Keith and Miranda"],oz:["Gil 和 Michael","Miranda 和 Gil","Michael 和 Keith","Keith 和 Miranda"],a:1,ex:"Miranda 回報進度與預算（We did a good job…），Gil 寫程式 → 兩人負責。Keith 只是去向 Michael 報告。"},
{n:63,q:"What does Miranda imply when she says, \"We did a good job managing our resources this time around\"?",qz:"Miranda 說「這次我們資源管理得很好」暗示什麼？",o:["The team needs a new manager.","The team didn't have enough resources.","The team learned from previous mistakes.","She wants to take credit for the team's success."],oz:["團隊需要新主管。","團隊資源不足。","團隊從之前的錯誤中學到了教訓。","她想搶團隊成功的功勞。"],a:2,ex:"this time around（這一次）暗示以前沒做好，這次改進了 → 從過去錯誤中學習。"},
{n:64,q:"What will Keith most likely do next?",qz:"Keith 接下來最可能做什麼？",o:["Meet with Miranda","Speak with Michael","Work on the software","Go over the team's budget"],oz:["和 Miranda 開會","和 Michael 談話","處理軟體","檢查團隊預算"],a:1,ex:"一開始他說幾分鐘後要去 Michael 的座位報告，問完資訊後就會去找 Michael。"}
]},
{ part: 7, title: "Part 7｜書架的投訴信",
passage: `<p>November 12<br>Mrs. Sandra Bell<br>84 Six Ave.,<br>San Francisco, California 94103</p><p>Dear Mrs. Bell,</p><p>I cannot begin to tell you how unsatisfied I am with my purchase of your Page bookshelf. My problem is not with the item itself, but with your company's deceptive advertising.</p><p>According to the infomercial, buyers normally pay four payments of $39.95. But, as a special offer, the price had been reduced by one payment of $39.95. They go on to say that the bookshelf comes fully assembled.</p><p>The item arrived with a receipt that listed an assembly fee of $39.95. This means I actually have to pay all four payments. When I called to complain, the operator told me I could send back the shelf, but I would forfeit the nonrefundable assembly fee. You claim a "money-back guarantee" but do not adhere to it.</p><p>I am returning the shelf. Not only do I expect the money I've paid to date (including the assembly fee) to be credited back to my credit card, I also expect an apology.</p><p>Sincerely,<br>Stephanie Kell</p>`,
pz: `<p>11 月 12 日<br>Sandra Bell 女士<br>舊金山第六大道 84 號</p><p>親愛的 Bell 女士：</p><p>我無法形容我對購買貴公司 Page 書架有多不滿意。我的問題不在商品本身，而在於貴公司的欺騙性廣告。</p><p>根據電視購物廣告，買家通常要分四期、每期付 $39.95。但作為特別優惠，價格減少了一期 $39.95。廣告還說書架送到時已完全組裝好。</p><p>商品寄到時附的收據上卻列了一筆 $39.95 的組裝費。這表示我實際上還是得付全部四期。我打電話抱怨時，接線員說我可以退回書架，但不退還組裝費。你們聲稱「保證退款」，卻不遵守。</p><p>我要退回書架。我不僅要求把至今已付的款項（包括組裝費）退回我的信用卡，還要求一個道歉。</p><p>Stephanie Kell 敬上</p>`,
qs: [
{n:65,q:"What is the purpose of this letter?",qz:"這封信的目的是什麼？",o:["To accompany a payment for a purchase","To complain about a delay in shipping","To inquire into a possible overcharge","To request action on a complaint"],oz:["隨附購物款項","抱怨出貨延遲","詢問可能的多收費","針對投訴要求處理"],a:3,ex:"她投訴廣告不實，並要求退款與道歉 → 要求對投訴採取行動。她不是在「詢問」，而是確定被騙並要求處理。"},
{n:66,q:"What does Stephanie give as an example of the company's \"deception\"?",qz:"Stephanie 舉什麼例子說明公司的「欺騙」？",o:["The company does not actually assemble the bookshelf.","The operator told her the four payments were nonrefundable.","The assembly of the bookshelf requires an extra charge.","The hosts on the infomercial do not use the bookshelf themselves."],oz:["公司其實沒有組裝書架。","接線員說四期款項都不退。","組裝書架要額外收費。","購物節目主持人自己不用這個書架。"],a:2,ex:"廣告說已組裝好、少付一期，結果另收 $39.95 組裝費 → 組裝要額外收費就是欺騙之處。"},
{n:67,q:"What does Stephanie demand from the company?",qz:"Stephanie 要求公司給什麼？",o:["Another bookshelf","A reduced assembly fee","A special offer","An apology"],oz:["另一個書架","降低組裝費","特別優惠","道歉"],a:3,ex:"「I also expect an apology」→ 道歉（以及全額退款）。"}
]},
{ part: 7, title: "Part 7｜M.I.T.T.S. 攤位報名表",
passage: `<p><b>MONTECLAIRE INTERNATIONAL TECHNOLOGY TRADE SHOW (M.I.T.T.S.) BOOTH REGISTRATION FORM</b></p><p>Company: ______<br>Address: ______<br>City/Town: ______ Province/State/County: ______<br>Country: ______ Telephone: ______<br>Fax (optional): ______</p><p>Main Contact (person who will attend the exhibit):<br>Name: ______ E-mail Address: ______</p><p>To assist in planning, please indicate which hotel you will be staying at while attending the M.I.T.T.S. (optional):<br>Hotel Name: ______<br>Check-in Date: ______ Check-out Date: ______</p><p>Exhibitor Space (please check your selection):<br>☐ Premium Booth Package: US$1,800<br>Includes: one of the more desirable locations within the convention hall; one table; four chairs; a 12' x 12' booth space; decorations; customized signage with your company's name and logo; four exhibitor passes</p><p>☐ Regular Booth Package: US$1,200<br>Includes: one table; two chairs; a 10' x 10' booth space; two exhibitor passes</p><p>All other services related to the trade show booth (including electricity, Wi-Fi, shipping, and storage) are the obligation of each exhibitor. Exhibitors without passes will be asked to leave.</p><p>Method of Payment (please check your selection)<br>Company Check ☐ Money Order ☐ Credit Card ☐</p><p>Fill in the following if paying by credit card:<br>Card Number: ______ Exp (MM/YY): ______<br>Card Holder's Signature: ______ Name (Print): ______</p><p>Exhibitors must submit this registration form with payment prior to April 12, 2017. Refunds for cancellation of booth spaces will be granted until April 12, 2017.<br>The Monteclaire International Technology Trade Show will begin on May 13, 2017 at 8:00 a.m. and conclude on May 14, 2017 at 9:00 p.m.</p><p><b>Confirmation:</b><br>A receipt for your successful registration will be e-mailed (or faxed by request) within one week after its reception by the M.I.T.T.S. If you do not receive this receipt by e-mail or fax within one week after submitting your form or if you have any other inquiries, please contact Mika Mordin by phone at 555-255-6889 ext. 990 or by e-mail at <u>tradeshowmordin@mitts.com</u>.</p>`,
pz: `<p><b>Monteclaire 國際科技貿易展（M.I.T.T.S.）攤位報名表</b></p><p>公司、地址、城市、省／州／郡、國家、電話（必填）；傳真（選填）</p><p>主要聯絡人（將出席展覽者）：姓名、電子郵件</p><p>為協助規劃，請註明參展期間將入住的飯店（選填）：飯店名稱、入住日期、退房日期</p><p>參展空間（請勾選）：<br>☐ 高級攤位方案：1,800 美元<br>包含：展場內較佳位置之一；一張桌子；四張椅子；12×12 呎攤位；布置；印有公司名稱與標誌的客製化招牌；四張參展證</p><p>☐ 一般攤位方案：1,200 美元<br>包含：一張桌子；兩張椅子；10×10 呎攤位；兩張參展證</p><p>其他所有與攤位相關的服務（包括電力、Wi-Fi、運送與倉儲）皆由參展商自行負責。沒有參展證的參展人員將被請離場。</p><p>付款方式（請勾選）：公司支票／匯票／信用卡</p><p>以信用卡付款請填寫：卡號、有效期限、持卡人簽名、姓名（正楷）</p><p>參展商必須在 2017 年 4 月 12 日之前連同款項提交此報名表。取消攤位的退款受理至 2017 年 4 月 12 日。<br>Monteclaire 國際科技貿易展將於 2017 年 5 月 13 日上午 8 點開始，5 月 14 日晚上 9 點結束。</p><p><b>確認：</b><br>M.I.T.T.S. 收到報名表後一週內，會以電子郵件（或依要求以傳真）寄送報名成功收據。若提交後一週內未收到收據，或有其他問題，請電洽 Mika Mordin：555-255-6889 分機 990，或寄信至 tradeshowmordin@mitts.com。</p>`,
qs: [
{n:68,q:"What information is required for exhibitors to provide?",qz:"參展商「必須」提供哪項資訊？",o:["Hotel name","Fax number","Check-in time","Company location"],oz:["飯店名稱","傳真號碼","入住時間","公司地點"],a:3,ex:"飯店資訊與傳真都標註 optional（選填）；公司地址（城市、國家等）是必填 → Company location。"},
{n:69,q:"On which date would a refund for cancellation be granted?",qz:"在哪一天取消可以獲得退款？",o:["April 10","May 12","May 13","April 13"],oz:["4 月 10 日","5 月 12 日","5 月 13 日","4 月 13 日"],a:0,ex:"退款受理到 4 月 12 日為止 → 只有 4 月 10 日在期限內。"},
{n:70,q:"How is a successful application confirmed?",qz:"報名成功是如何確認的？",o:["Via e-mail","Via telephone","Via mail","Via text message"],oz:["電子郵件","電話","郵寄","簡訊"],a:0,ex:"「A receipt for your successful registration will be e-mailed」→ 電子郵件（或依要求傳真）。"},
{n:71,q:"When would it be necessary for your company to purchase the premium booth package?",qz:"什麼情況下公司「必須」購買高級攤位方案？",o:["When your booth requires at least 8' x 8' of space","When you require an abundance of electrical outlets","When you will need to leave the convention hall one day early","When you require more than two representatives at your booth"],oz:["攤位至少需要 8×8 呎時","需要大量插座時","需要提早一天離開展場時","攤位需要超過兩位代表時"],a:3,ex:"一般方案只有 2 張參展證，沒有證的人會被請離場；需要超過 2 人就得買有 4 張證的高級方案。一般方案 10×10 已超過 8×8；電力要自理。"}
]},
{ part: 7, title: "Part 7｜Genevieve 手寫書法",
passage: `<p>In this day and age of rushed e-mails and text messages that abbreviate words to a few letters, it's increasingly rare to see beautiful, stylish writing. Yet nothing could be more heartfelt than a message thoughtfully composed by a writer absorbed in the tactile experience of setting meaning down to paper by hand. —[1]—</p><p>—[2]— This is the idea behind Genevieve's specially designed, handwritten stationery. Since 1995, Genevieve has been learning calligraphy under teachers of several distinct styles within the Western calligraphy tradition.</p><p>You can browse the catalogue of products by theme (such as wedding, thank you, and dinner party) or by type (such as invitations, greeting cards, and place cards). —[3]— Custom orders are welcome.</p><p>Genevieve also teaches calligraphy. Dates for online teaching programs are listed on the right. —[4]— Use the contact form to inquire about more details.</p>`,
pz: `<p>在這個電子郵件匆忙、簡訊把單字縮寫成幾個字母的時代，要看到優美、有風格的字跡越來越少見了。然而，沒有什麼比一位沉浸於親手把意義寫在紙上的觸感、用心寫下的訊息更真摯動人。—[1]—</p><p>—[2]— 這就是 Genevieve 特別設計的手寫信紙文具背後的理念。從 1995 年起，Genevieve 就跟隨西方書法傳統中好幾種不同風格的老師學習書法。</p><p>您可以依主題（如婚禮、感謝、晚宴）或類型（如邀請函、賀卡、座位卡）瀏覽產品目錄。—[3]— 歡迎客製化訂單。</p><p>Genevieve 也教書法。線上課程的日期列在右側。—[4]— 她也可以開設實體工作坊。請使用聯絡表單詢問更多細節。</p>`,
qs: [
{n:72,q:"How does the text describe handwritten messages?",qz:"文章如何描述手寫訊息？",o:["Earnest","Hurried","Outdated","Commonplace"],oz:["真摯的","匆忙的","過時的","平凡的"],a:0,ex:"「nothing could be more heartfelt than a message…by hand」→ heartfelt ≈ earnest（真誠的）。Hurried 是在形容電子郵件。"},
{n:73,q:"What can one learn from Genevieve?",qz:"可以跟 Genevieve 學什麼？",o:["How to plan weddings","How to throw a dinner party","How to make stationery","How to produce calligraphy"],oz:["如何策劃婚禮","如何辦晚宴","如何製作文具","如何寫書法"],a:3,ex:"「Genevieve also teaches calligraphy」→ 學書法。"},
{n:74,q:"Which is most likely to be one of Genevieve's products?",qz:"下列哪一個最可能是 Genevieve 的產品？",o:["A legal letter","A grant proposal","A party invitation","An application form"],oz:["法律信函","補助申請計畫書","派對邀請函","申請表"],a:2,ex:"產品類型包括 invitations（邀請函），主題有 dinner party → 派對邀請函。"},
{n:75,q:"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"She is also available for in-person workshops.\"",qz:"下列句子最適合放在哪個位置？\n「她也可以開設實體工作坊。」",o:["[1]","[2]","[3]","[4]"],oz:["[1]","[2]","[3]","[4]"],a:3,ex:"[4] 前一句講「線上課程」，also 接著補充「也有實體工作坊」，後面再請大家用表單詢問 → 最連貫。"}
]},
{ part: 7, title: "Part 7｜捷運失物招領",
passage: `<table><tr><th colspan="2">LOST AND FOUND ARTICLES</th></tr><tr><td>Name:</td><td>Miranda Smithers</td></tr><tr><td>Telephone number:</td><td>please e-mail <u>m.smithers@yahoo.com</u></td></tr><tr><td>Missing article(s):</td><td>Turquoise short velvet jacket, button-up, with pockets. One of the pockets had my business cards inside—so you can be sure it's mine!</td></tr><tr><td>Last seen in place:</td><td>On the train between Main and Kunyang MRT stops, Blue Line</td></tr><tr><td>Last seen on date:</td><td>December 21, about 3:00 p.m.</td></tr><tr><td>Other comments:</td><td>I am only in Taipei for a few more days before I return to Hong Kong for Christmas with my family. This is why I don't have a phone number, and I don't have the number of the friend I'm staying with on me.<br><br>I hope the jacket turns up. Thanks very much.</td></tr></table><p>To: m.smithers@yahoo.com<br>From: a.wang@metro.taipei.com<br>Date: Mon, Dec. 26, 7:35 a.m.</p><p>Dear Ms. Smithers,</p><p>We have found a jacket that matches your description. Please call us at 02-2542-4511 or come to the Lost and Found office at Taipei Main Station. We are open 9:00 a.m. – 6:00 p.m. Monday-Friday.</p><p>Best wishes,</p><p>Adele Wang</p>`,
pz: `<p><b>失物登記表</b><br>姓名：Miranda Smithers<br>電話：請寄信至 m.smithers@yahoo.com<br>遺失物品：土耳其藍短版絲絨外套，有釦子和口袋。其中一個口袋裡有我的名片——所以你可以確定那是我的！<br>最後出現地點：藍線捷運，台北車站與昆陽站之間的列車上<br>最後出現日期：12 月 21 日下午 3 點左右<br>其他說明：我只會在台北再待幾天，之後就要回香港和家人過聖誕節。所以我沒有電話號碼，身上也沒有我借住的朋友的電話。希望外套能找到。非常感謝。</p><p>收件者：m.smithers@yahoo.com<br>寄件者：a.wang@metro.taipei.com<br>日期：12 月 26 日（週一）上午 7:35</p><p>親愛的 Smithers 小姐：</p><p>我們找到一件符合您描述的外套。請致電 02-2542-4511 或到台北車站的失物招領處。我們的服務時間是週一至週五上午 9 點至下午 6 點。</p><p>祝好，<br>Adele Wang</p>`,
qs: [
{n:76,q:"Why did Miranda leave her e-mail instead of a contact number?",qz:"Miranda 為什麼留電子郵件而不是電話？",o:["She lost her phone.","She misunderstood the form.","She hasn't paid her phone bill.","She doesn't have a local number."],oz:["她弄丟了手機。","她誤解了表格。","她沒繳電話費。","她沒有當地電話號碼。"],a:3,ex:"她只是短暫在台北，「This is why I don't have a phone number」→ 沒有台灣當地號碼。"},
{n:77,q:"Where did Miranda lose the item?",qz:"Miranda 在哪裡遺失物品？",o:["At Kunyang MRT station","At the airport","At Taipei Bus Station","On the subway"],oz:["在昆陽捷運站","在機場","在台北轉運站","在地鐵（捷運）上"],a:3,ex:"「On the train between Main and Kunyang MRT stops」→ 在捷運列車上，不是在車站。"},
{n:78,q:"What do we know about Miranda?",qz:"關於 Miranda 我們知道什麼？",o:["She is still in Taiwan.","She likely did not receive her jacket.","She can receive her item through the mail.","She will spend Christmas with her friend in Taipei."],oz:["她還在台灣。","她可能沒拿到外套。","她可以透過郵寄收到物品。","她會和台北的朋友過聖誕。"],a:1,ex:"回信日期是 12/26（聖誕節後），而她只在台北再待幾天就回香港過聖誕 → 很可能已離開，拿不到外套。"},
{n:79,q:"How can Miranda reclaim her jacket?",qz:"Miranda 要如何領回外套？",o:["Call and leave her friend's number","Fill out a form and fax or bring it in","Go to the office before 6:00 p.m. any day","Go to the office on a weekday morning"],oz:["打電話留下朋友的號碼","填表後傳真或親自送來","任何一天下午 6 點前到辦公室","平日早上到辦公室"],a:3,ex:"開放時間是週一到週五 9:00–18:00 → 平日早上去可以。(C) any day 錯，週末不開。"},
{n:80,q:"Who most likely is Adele Wang?",qz:"Adele Wang 最可能是誰？",o:["A train driver on the MRT","Miranda Smithers's friend in Taipei","Miranda Smithers's friend in Hong Kong","An employee at the Lost and Found office"],oz:["捷運列車司機","Miranda 在台北的朋友","Miranda 在香港的朋友","失物招領處的員工"],a:3,ex:"她用 metro.taipei.com 信箱、通知找到外套並請對方來失物招領處 → 失物招領處員工。"}
]},
{ part: 7, title: "Part 7｜團隊主管職位推薦",
passage: `<p>Dear Ms. Marple,</p><p>I am a friend of Jackie Chen's. She told me that you are currently looking to fill her former position of team leader, and she believes that I would be a suitable replacement. Jackie always spoke well of her workplace, and I believe I would be a good fit because of my previous experience in the field.</p><p>I have attached my résumé and a few samples of my previous work as a graphic designer. This is just to give you an idea of my background. I understand that the position is more managerial in nature.</p><p>Sincerely,</p><p>Roberta Bond</p><hr><p>Dear Roberta,</p><p>Thank you for your e-mail. Your résumé looks very good, and we loved Jackie, so her recommendation definitely carries weight with us. Can you come in for an interview this Thursday or Friday at 2:00 p.m.? If not, what alternate times are you available?</p><p>Looking forward to meeting you,</p><p>Jane Marple</p>`,
pz: `<p>親愛的 Marple 女士：</p><p>我是 Jackie Chen 的朋友。她告訴我，您目前正在找人接替她之前的團隊主管職位，而她認為我會是合適的人選。Jackie 總是稱讚她的工作環境，而我相信憑藉我過去在這個領域的經驗，我會很適合這份工作。</p><p>我附上了履歷以及幾份我過去擔任平面設計師的作品樣本。這只是讓您了解我的背景。我了解這個職位本質上更偏向管理。</p><p>Roberta Bond 敬上</p><hr><p>親愛的 Roberta：</p><p>謝謝你的來信。你的履歷看起來很好，而我們都很喜歡 Jackie，所以她的推薦對我們來說絕對有份量。你可以在這週四或週五下午 2 點來面試嗎？如果不行，你還有哪些時間方便？</p><p>期待與你見面，</p><p>Jane Marple</p>`,
qs: [
{n:81,q:"Which is the closest in meaning to \"in nature\" in the first e-mail?",qz:"第一封郵件中「in nature」的意思最接近哪一個？",o:["Outdoors","In essence","Instead of","As of now"],oz:["在戶外","本質上","而不是","截至目前"],a:1,ex:"more managerial in nature ＝ 本質上更偏管理 → in essence。不是「大自然」的意思。"},
{n:82,q:"What kind of work will the position most likely require?",qz:"這個職位最可能需要做什麼樣的工作？",o:["Writing résumés","Managing projects","Lifting heavy objects","Finding Jackie's replacement"],oz:["寫履歷","管理專案","搬重物","找 Jackie 的接班人"],a:1,ex:"職位是 team leader，且 more managerial in nature → 管理專案。"},
{n:83,q:"What can we infer about Jackie from the exchange?",qz:"從往來信件可以推論出關於 Jackie 的什麼？",o:["She had a falling-out with her coworkers.","She felt weighed down by her previous job.","She and her former colleagues had a good relationship.","She liked her colleagues, but her feelings were not reciprocated."],oz:["她和同事鬧翻了。","她覺得以前的工作讓她喘不過氣。","她和前同事關係很好。","她喜歡同事，但同事不喜歡她。"],a:2,ex:"Jackie always spoke well of her workplace，Jane 也說 we loved Jackie → 雙方關係良好。"},
{n:84,q:"Which is NOT a likely reason that Roberta was invited for an interview?",qz:"下列何者「不是」Roberta 被邀請面試的可能原因？",o:["She has met Jane before.","She has worked in the field before.","She has the appropriate qualifications.","She was recommended by a former employee."],oz:["她以前見過 Jane。","她以前在這個領域工作過。","她具備適當的資格。","她是前員工推薦的。"],a:0,ex:"Jane 說 Looking forward to meeting you → 兩人還沒見過面。其他三項文中都有依據。"},
{n:85,q:"What has Jane requested that Roberta do before the interview?",qz:"Jane 要求 Roberta 在面試前做什麼？",o:["Contact Jackie","Purchase professional clothing","Send the company her portfolio","Respond with an appointment time"],oz:["聯絡 Jackie","買正式服裝","寄作品集給公司","回覆可以面試的時間"],a:3,ex:"Jane 問週四或週五 2 點可否，若不行請告知其他時間 → 回覆面試時間。作品集已經寄過了。"}
]},
{ part: 7, title: "Part 7｜Bodymeant 智慧體重計",
passage: `<p style="text-align:center"><b><i>The all-new, revolutionary Bodymeant™ smart scale.</i></b></p><p>The all-new Bodymeant™ smart scale is all you need to get back in shape or stay there. Simply step on the scale and our high-tech sensors will tell you your weight, body-fat percentage, muscle percentage, and more.</p><p>The Bodymeant™ scale will also give you goals based on the recommendations of our in-house nutritionists. Users of our scale report an average weight loss of 11 lbs. Some users have even lost over 100 lbs.</p><p>If you order before February 1, we'll also throw in our <i>Bodymeant™ Fitness Guide</i>. It includes great beginner exercises and healthy recipes to help you shed the pounds. Go to www.bodymeant.com today to find out more!</p><hr><p>Dear Customer Service department,</p><p>Hello, my name is Walter Pinkman. I purchased your product four months ago to lose weight. While I'm mostly pleased with the product, I've encountered a problem. When I first began using your product, the scale analyzed me and stated I was 202 lbs, 25 percent muscle, and 24 percent body fat. After three months of working out, I got down to 195 lbs, 28 percent muscle, and very strangely . . . 31 percent body fat. It somehow went up! I believe there might be a problem with whatever the device uses to produce these measurements, and I'm very skeptical about the measurements' accuracy (apart from weight). Or perhaps the recipes in your fitness guide haven't been so healthy! I no longer trust your product, and I would like to request a refund.</p><p>Respectfully,<br>Walter</p><p>PS: If you need proof, I took photographs of the readings the scale gave me. I have also attached a copy of the first scan.</p><hr><p><b><i>Bodymeant™ Scan Results</i></b><br>User: walter_pinkman5874</p><p><i>The below results are meant to be used as a reference for where your body is at currently, and also offer some goals for the user. Always consult a doctor before beginning any exercise program.</i></p><table><tr><th>Yours</th><th></th><th>Target</th></tr><tr><td>202 lbs</td><td>Weight</td><td>195 lbs</td></tr><tr><td>25%</td><td>Muscle %</td><td>35%</td></tr><tr><td>24%</td><td>Body Fat %</td><td>19%</td></tr><tr><td>36"*</td><td>Waist Size</td><td>32"</td></tr></table><p>*estimated</p>`,
pz: `<p style="text-align:center"><b>全新革命性 Bodymeant™ 智慧體重計</b></p><p>全新 Bodymeant™ 智慧體重計，是你恢復身材或保持身材所需的一切。只要站上體重計，我們的高科技感測器就會告訴你體重、體脂率、肌肉率等數據。</p><p>Bodymeant™ 體重計還會根據我們自家營養師的建議為你設定目標。使用者回報平均減重 11 磅，有些人甚至減了 100 磅以上。</p><p>若在 2 月 1 日前訂購，我們還會加贈《Bodymeant™ 健身指南》，內含很棒的入門運動與健康食譜，幫你甩掉贅肉。今天就上 www.bodymeant.com 了解更多！</p><hr><p>親愛的客服部門：</p><p>你好，我是 Walter Pinkman。我四個月前為了減重購買了你們的產品。雖然我大致滿意，但遇到了一個問題。剛開始使用時，體重計分析我是 202 磅、肌肉 25%、體脂 24%。運動三個月後，我降到 195 磅、肌肉 28%，而且非常奇怪……體脂 31%。體脂竟然上升了！我認為這台裝置用來產生測量數據的方式可能有問題，我非常懷疑測量的準確度（體重除外）。或者你們健身指南裡的食譜其實沒那麼健康！我不再信任你們的產品，想申請退款。</p><p>Walter 敬上</p><p>附註：如果需要證據，我有拍下體重計的讀數。我也附上了第一次掃描結果。</p><hr><p><b>Bodymeant™ 掃描結果</b>　使用者：walter_pinkman5874</p><p><i>以下結果供您參考目前身體狀況，並提供一些目標。開始任何運動計畫前，請務必先諮詢醫師。</i></p><p>體重：202 磅 → 目標 195 磅<br>肌肉率：25% → 目標 35%<br>體脂率：24% → 目標 19%<br>腰圍：36 吋（估計）→ 目標 32 吋</p>`,
qs: [
{n:86,q:"What claim does the advertisement make about the product?",qz:"廣告對產品做了什麼宣稱？",o:["It can help users lose weight.","It is very nutritious.","It has a unique shape.","The scale only weighs 1.1 lbs."],oz:["它能幫使用者減重。","它非常營養。","它的造型獨特。","體重計只有 1.1 磅重。"],a:0,ex:"「Users of our scale report an average weight loss of 11 lbs」→ 宣稱能幫助減重。"},
{n:87,q:"What do we know about Mr. Pinkman?",qz:"關於 Pinkman 先生我們知道什麼？",o:["He is in great shape.","He is overweight.","He has already hit his goals.","He is a doctor."],oz:["他身材很好。","他體重過重。","他已達成目標。","他是醫生。"],a:1,ex:"他買產品是為了減重，掃描結果體重 202 磅高於目標 195 磅 → 過重。肌肉與體脂都還沒達標。"},
{n:88,q:"What is true about Mr. Pinkman?",qz:"關於 Pinkman 先生，下列何者為真？",o:["His device malfunctioned.","He used the scale incorrectly.","He didn't actually use the scale.","He ordered the scale before February 1."],oz:["他的裝置故障了。","他用錯體重計了。","他其實沒用體重計。","他在 2 月 1 日前訂購了體重計。"],a:3,ex:"他提到「your fitness guide 的食譜」，而健身指南只送給 2 月 1 日前訂購的人 → 他在 2/1 前訂購。故障只是他的懷疑，未被證實。"},
{n:89,q:"What problem did Mr. Pinkman mention in his e-mail?",qz:"Pinkman 先生在信中提到什麼問題？",o:["His scale failed to analyze his body.","The product made him gain weight.","His scale arrived at his house broken.","He thinks the scale is inaccurate."],oz:["體重計無法分析他的身體。","產品讓他變胖。","體重計送到時就壞了。","他認為體重計不準確。"],a:3,ex:"「I'm very skeptical about the measurements' accuracy」→ 他認為不準。他的體重其實減少了。"},
{n:90,q:"What should you do before beginning an exercise program?",qz:"開始運動計畫前應該做什麼？",o:["Consult the Bodymeant™ Fitness Guide","Get your Bodymeant™ scan results","Weigh yourself","Ask for a doctor's opinion"],oz:["參考 Bodymeant™ 健身指南","取得 Bodymeant™ 掃描結果","量體重","徵詢醫師意見"],a:3,ex:"掃描結果上寫「Always consult a doctor before beginning any exercise program」→ 諮詢醫師。"}
]},
{ part: 7, title: "Part 7｜PerfectAbs 電擊健腹機",
passage: `<p>Do you want ripped abs? Do you want to work out in the comfort of your own home? Then you need PerfectAbs! With state-of-the-art tech, our new machine will give your abs the workout of a lifetime—and you don't even need to move. Thanks to our patented Electro Ab Shock technology, you can train your abs right in front of your TV. All you need to do is apply conductivity jelly directly on your stomach, attach the electrode pads, and activate your PerfectAbs machine. By administering constant mini electric shocks, the machine passively exercises your abdominal muscles simply and painlessly. So what are you waiting for? If you want perfect abs, order today!</p><p>Warning: Do not increase voltage. Remain stationary while using machine. Shave abdominal hair before use. Do not place anything between electrode pads and jelly.</p><hr><p>Dear PerfectAbs,</p><p>Recently, I purchased your product online after seeing your late-night infomercial. As I am sure you are aware, your infomercial describes how your product passively exercises its wearer's abdominal muscles by causing them to tense up involuntarily via electric shocks. The process was described as both painless and simple. Imagine my surprise when, after carefully reading the instructions, smearing the conductivity jelly on my stomach, and activating my PerfectAbs, I was so severely electrocuted that my stomach hairs burned away and my skin blistered. Needless to say, I ripped the product off my body and haven't used it since. I expect a full refund for my troubles, as I paid for a product which would exercise my muscles, not electrocute me to death.</p><p>Sincerely,</p><p>Abraham McDoil</p><hr><p>Dear Mr. McDoil,</p><p>We sincerely apologize that our product caused you so much duress. We will be refunding you the full amount of your purchase. As our product experienced no such malfunctions in over 100,000 simulations and 10,000 individual product trials, we would greatly appreciate your taking the time to clarify the following details so that we may ensure the future safety of our customers:</p><p>1. Did you modify your PerfectAbs in some way to increase the voltage?<br>2. Did you place anything between the product and your skin besides the conductivity jelly?<br>3. What were your surroundings when you activated the product?<br>4. Were you doing anything else when you activated the product?</p><p>The more details you provide, the more likely we are to determine just what went wrong. Please return your PerfectAbs by mail so that we may examine the model you received. You will be reimbursed for the shipping. If you have any further questions, please don't hesitate to contact our customer service department again at 1-555-454-3212 or e-mail us at <u>customersupport@perfectabs.com</u>.</p><p>Sincerely,</p><p>Michael Richards<br>Customer Service Representative<br>PerfectAbs Company: a subsidiary of Coalman &amp; Grundy</p>`,
pz: `<p>想要明顯的腹肌嗎？想在舒適的家中運動嗎？那你需要 PerfectAbs！採用最先進的科技，我們的新機器能讓你的腹肌得到一生難得的鍛鍊——而且你連動都不用動。多虧我們的專利電擊健腹技術，你可以在電視前就鍛鍊腹肌。只要把導電凝膠直接塗在肚子上，貼上電極片，啟動 PerfectAbs 機器即可。機器透過持續施加微小電擊，簡單又無痛地被動鍛鍊你的腹肌。還在等什麼？想要完美腹肌，今天就訂購！</p><p>警告：請勿調高電壓。使用時保持靜止不動。使用前請剃除腹部毛髮。電極片與凝膠之間請勿放置任何東西。</p><hr><p>親愛的 PerfectAbs：</p><p>我最近看了你們的深夜購物節目後在網路上買了產品。相信你們也知道，廣告描述產品如何透過電擊讓腹肌不自主收縮，被動地鍛鍊使用者的腹肌，過程被形容為無痛又簡單。想像一下我有多驚訝：在仔細閱讀說明書、把導電凝膠塗在肚子上並啟動 PerfectAbs 後，我被嚴重電擊，肚子上的毛都燒掉了，皮膚還起了水泡。不用說，我把產品從身上扯下來，之後再也沒用過。我要求全額退款，因為我花錢買的是能鍛鍊肌肉的產品，不是要把我電死的東西。</p><p>Abraham McDoil 敬上</p><hr><p>親愛的 McDoil 先生：</p><p>我們誠摯地為產品給您帶來的痛苦致歉。我們將全額退還您的購買金額。由於我們的產品在超過 10 萬次模擬及 1 萬次個別產品試驗中從未發生這種故障，若您能撥冗說明以下細節，我們將非常感激，以確保日後顧客的安全：</p><p>1. 您是否以任何方式改裝 PerfectAbs 以提高電壓？<br>2. 除了導電凝膠之外，您是否在產品與皮膚之間放了任何東西？<br>3. 您啟動產品時周遭環境如何？<br>4. 您啟動產品時是否正在做其他事？</p><p>您提供的細節越多，我們越有可能找出問題所在。請將您的 PerfectAbs 郵寄退回，以便我們檢查您收到的機型。運費將由我們補貼。如有任何問題，歡迎再次聯絡客服部門：1-555-454-3212，或寄信至 customersupport@perfectabs.com。</p><p>Michael Richards 敬上<br>客服代表<br>PerfectAbs 公司（Coalman &amp; Grundy 子公司）</p>`,
qs: [
{n:91,q:"What is the PerfectAbs supposed to do?",qz:"PerfectAbs 應該要有什麼功用？",o:["Relax the user with gentle jolts of electricity","Tone the user's abdomen with surges of electricity","Wake the user up with a powerful shock of electricity","Balance the user's mental state with a field of electricity"],oz:["用溫和電流讓使用者放鬆","用電流鍛鍊、緊實使用者的腹部","用強力電擊叫醒使用者","用電場平衡使用者心理狀態"],a:1,ex:"機器透過微電擊被動鍛鍊腹肌 → tone the abdomen（緊實腹部）。"},
{n:92,q:"Why is Abraham McDoil demanding a refund?",qz:"Abraham McDoil 為什麼要求退款？",o:["Because he was charged twice","Because he was sent the wrong product","Because his product could not be turned on","Because the product seems to have malfunctioned"],oz:["因為被重複收費","因為寄錯產品","因為產品打不開","因為產品似乎故障了"],a:3,ex:"他被嚴重電傷，認為產品出了問題 → 看起來故障。"},
{n:93,q:"Which warning did Abraham McDoil likely overlook?",qz:"Abraham McDoil 可能忽略了哪一項警告？",o:["Do not move while using.","Do not increase power of machine.","Do not use without shaving body hair.","Do not place anything between pads and jelly."],oz:["使用時不要移動。","不要調高機器電力。","沒剃體毛不要使用。","電極片和凝膠之間不要放東西。"],a:2,ex:"他說 my stomach hairs burned away（肚毛燒掉了）→ 他沒有先剃毛，違反「Shave abdominal hair before use」。"},
{n:94,q:"Why does Michael Richards seem surprised to learn that the product reportedly malfunctioned?",qz:"Michael Richards 為什麼對產品據報故障感到驚訝？",o:["Because the product has been thoroughly tested","Because this has happened to Abraham McDoil before","Because the product does not come with conductivity jelly","Because the malfunction described is physically impossible"],oz:["因為產品經過徹底測試","因為這種事以前也發生在 Abraham 身上","因為產品沒附導電凝膠","因為描述的故障在物理上不可能"],a:0,ex:"「no such malfunctions in over 100,000 simulations and 10,000 individual product trials」→ 經過大量測試。"},
{n:95,q:"What is something Michael Richards requests Abraham McDoil do?",qz:"Michael Richards 請 Abraham McDoil 做什麼？",o:["Not tell anyone about the malfunction","Exchange his PerfectAbs for a new one free of charge","Use his PerfectAbs again to discover what went wrong","Explain in detail what he was doing when the malfunction occurred"],oz:["不要告訴任何人這次故障","免費換一台新的 PerfectAbs","再用一次找出問題","詳細說明故障發生時他在做什麼"],a:3,ex:"他列出四個問題請對方說明，並說 The more details you provide… → 請他詳細說明。"}
]},
{ part: 7, title: "Part 7｜Riftware 軟體訂閱",
passage: `<p>Note: Please do not reply to this message</p><p>Dear Mr. Lowell,</p><p>Riftware cannot charge the credit card you have been using to subscribe. For more information regarding your credit card error, please contact your bank.</p><p>　Product: Riftware Operating and Accounting System (Office Version)<br>　Last Renewal: January 18, 2016 at 11:54 Greenwich Mean Time<br>　Payment Method: VISA ************4456 / Exp. 01/12/2016</p><p>To avoid an interruption of your subscription, please provide valid credit card information.</p><p>To update your payment information, please proceed to <u>riftware.com/myaccount</u>.</p><p>If you have already addressed this issue, then please ignore this message.</p><p>If you are interested in purchasing some of our other products, such as computer games or accessories, please visit <u>riftware.com/store</u>.</p><p>Thank you for subscribing to Riftware's Services.</p><p>The Riftware Team</p><hr><p>From: riftware.com<br>To: r.lowell@email4days.com</p><p>Good afternoon Mr. Lowell,</p><p>Thank you for your order. Below is some necessary information regarding your order:<br>Your Riftware Operating and Accounting System (Office Version) subscription is authorized for download. Proceed to <u>riftware.com/myaccount/download</u> to begin the downloading and installation process.</p><p>Thank you again,</p><p>The Riftware Team</p><table><tr><td><b>Order number:</b><br>134550450908981</td><td><b>Bill to:</b><br>Red Lowell<br>10045 127 Street<br>Valemont, NB, T556Z5<br>Canada<br>1-9555-620-6979<br>r.lowell@email4days.com</td></tr><tr><td><b>Order date:</b><br>January 19, 2017 at 13:54 GMT</td><td><b>Payment:</b><br>VISA<br>**********5567 / Exp. 04/12/2020</td></tr><tr><td><b>Products in your order:</b><br><u>Riftware Operating and Accounting System (Office Version)</u><br>Qty ordered: 1</td><td><b>Amount:</b><br>C$299.00<br><br>Subtotal: C$299.00<br>GST/HST: C$14.95<br>Total: C$313.95</td></tr><tr><td colspan="2"><u>Riftware Operating and Accounting System (Office Version):</u><br>Thank you for purchasing the 12-month membership to Riftware Operating and Accounting System (Office Version). Your credit card has been charged. Your membership will renew automatically unless you cancel before the renewal date. If you wish to upgrade or cancel your subscription, go to <u>riftware.com/myaccount</u>.</td></tr></table><hr><p><b>MEMORANDUM</b></p><p>To: All Staff<br>From: Red Lowell, President<br>Date: January 20, 2017<br>Subject: Riftware software</p><p>This morning, it came to my attention that many staff members are displeased with our operating and accounting system. However, I feel our current software is best suited for our company. It's reliable and gets the job done. I'm aware that there are other higher-performing—and more expensive—options on the market. Unfortunately, due to budget constraints, we will stick with Riftware. It may seem a bit lacking, but I assure you, it's the best and only option we have.</p><p>Thank you for your understanding and cooperation.</p><p>Best,<br>Red Lowell</p>`,
pz: `<p>注意：請勿回覆此訊息</p><p>親愛的 Lowell 先生：</p><p>Riftware 無法向您用於訂閱的信用卡扣款。有關信用卡錯誤的詳情，請聯絡您的銀行。</p><p>　產品：Riftware 作業與會計系統（辦公室版）<br>　上次續訂：2016 年 1 月 18 日 11:54（格林威治時間）<br>　付款方式：VISA 卡末四碼 4456／到期日 2016/01/12</p><p>為避免訂閱中斷，請提供有效的信用卡資料。請至 riftware.com/myaccount 更新付款資訊。</p><p>若您已處理此問題，請忽略此訊息。</p><p>若您有興趣購買我們的其他產品，例如電腦遊戲或配件，請造訪 riftware.com/store。</p><p>感謝您訂閱 Riftware 的服務。Riftware 團隊</p><hr><p>寄件者：riftware.com　收件者：r.lowell@email4days.com</p><p>Lowell 先生午安：</p><p>感謝您的訂購。以下是您訂單的必要資訊：您的 Riftware 作業與會計系統（辦公室版）訂閱已獲授權下載。請至 riftware.com/myaccount/download 開始下載與安裝。</p><p>再次感謝，Riftware 團隊</p><p>訂單編號：134550450908981<br>帳單寄送：Red Lowell，加拿大新布倫瑞克省 Valemont<br>訂購日期：2017 年 1 月 19 日 13:54 GMT<br>付款：VISA 末四碼 5567／到期日 2020/04/12<br>訂購產品：Riftware 作業與會計系統（辦公室版）×1<br>金額：小計 C$299.00；商品及服務稅 C$14.95；總計 C$313.95<br>感謝您購買 Riftware 作業與會計系統（辦公室版）12 個月會員。您的信用卡已扣款。除非您在續訂日前取消，會員資格將自動續訂。若想升級或取消訂閱，請至 riftware.com/myaccount。</p><hr><p><b>備忘錄</b></p><p>致：全體員工<br>發文：總裁 Red Lowell<br>日期：2017 年 1 月 20 日<br>主旨：Riftware 軟體</p><p>今天早上我注意到許多員工對我們的作業與會計系統不滿意。不過，我認為目前的軟體最適合我們公司。它穩定可靠，能把工作完成。我知道市面上還有其他效能更好、也更貴的選擇。很遺憾，由於預算限制，我們會繼續使用 Riftware。它可能看起來有點不足，但我向各位保證，這是我們最好也是唯一的選擇。</p><p>感謝各位的體諒與配合。</p><p>Red Lowell</p>`,
qs: [
{n:96,q:"What was the purpose of the automated message?",qz:"這封自動訊息的目的是什麼？",o:["To inform the receiver that his service will expire soon","To inform the receiver about a Riftware (Office Version) update","To inform the receiver that there has been a renewal payment error","To inform the receiver that his credit card information has been updated"],oz:["通知收件人服務即將到期","通知收件人軟體更新","通知收件人續訂付款發生錯誤","通知收件人信用卡資料已更新"],a:2,ex:"「Riftware cannot charge the credit card you have been using」→ 續訂扣款失敗。"},
{n:97,q:"What can be safely assumed from the automated message and e-mail?",qz:"從自動訊息與郵件可以合理推斷出什麼？",o:["Red Lowell is not Canadian.","Red Lowell is the CEO of a software company.","Red Lowell's credit card information has been stolen.","Red Lowell's company has been a Riftware customer for over a year."],oz:["Red Lowell 不是加拿大人。","Red Lowell 是軟體公司的執行長。","Red Lowell 的信用卡資料被盜了。","Red Lowell 的公司當 Riftware 客戶超過一年了。"],a:3,ex:"上次續訂是 2016 年 1 月 18 日，2017 年 1 月又續訂 → 已使用超過一年。他住加拿大；是總裁但公司不是軟體公司。"},
{n:98,q:"What did Red Lowell most likely do in the interim between the automated message and e-mail?",qz:"在自動訊息和訂單郵件之間，Red Lowell 最可能做了什麼？",o:["Canceled his subscription","Made another purchase","Updated his payment information","Completed the rest of his day's work"],oz:["取消了訂閱","買了別的東西","更新了付款資料","完成了當天剩下的工作"],a:2,ex:"原本的卡（4456）已過期，新訂單用的是另一張卡（5567）→ 他更新了付款資料。"},
{n:99,q:"Which of the following products does Riftware least likely sell?",qz:"下列哪一項產品 Riftware 最不可能販售？",o:["Software","Cell phones","Accessories","Computer games"],oz:["軟體","手機","配件","電腦遊戲"],a:1,ex:"文中提到軟體、電腦遊戲和配件，沒有提到手機。"},
{n:100,q:"Which of the following statements is NOT correct?",qz:"下列哪一項敘述「不」正確？",o:["Red Lowell's company is limited by its budget.","Riftware's software can be downloaded after it is purchased.","Red Lowell can upgrade his subscription on Riftware's Web site.","Red Lowell re-subscribed knowing his employees were unhappy with Riftware."],oz:["Red Lowell 的公司受預算限制。","Riftware 軟體購買後可下載。","Red Lowell 可在網站上升級訂閱。","Red Lowell 是在知道員工不滿的情況下續訂的。"],a:3,ex:"他 1/19 續訂，備忘錄 1/20 才寫「今天早上」才得知員工不滿 → 續訂時並不知道，所以 (D) 不正確。"}
]}
]
});
